    var d = 'M ' + f1(pts[0].x) + ' ' + f1(pts[0].y), last = pts[pts.length - 1];
    for(var k = 1; k + 1 < pts.length; k++){
      var p = pts[k], u = unit(pts[k - 1], p), v = unit(p, pts[k + 1]);
