        'aria-label':'Show the routes of the group ' + g.say + '. ' + plural(n, 'flow') + '.'});
      badge.appendChild(el('circle', {'class':'fg-badge__ring', cx:cx, cy:cy, r:r + 4.5}));
      badge.appendChild(el('circle', {'class':'fg-badge__c', cx:cx, cy:cy, r:r}));
